export const STUDY_VERSION='v43-1';
export const STUDY_CASES=[
 {id:'wide',title:'The unseen run',time:16,questions:[
  {id:'gain',text:'What does forward passing gain describe?',choices:['How far the winger ran','The ball’s advance toward goal through completed passes','The chance of scoring'],answer:1},
  {id:'cause',text:'The winger and defender move toward the same side. What can we conclude?',choices:['The winger definitely caused the defender to move','The run had no effect','Their movements coincide; the cause is not established'],answer:2},
  {id:'revision',text:'A corrected record keeps the defender in place. What should change?',choices:['Withdraw the defender-movement claim; keep the completed passes','Delete the completed passes','Keep the original movement story'],answer:0}]},
 {id:'press',title:'Pressure with purpose',time:29,questions:[
  {id:'tempo',text:'What does regain-to-shot time measure?',choices:['The interval from winning the ball to the shot’s release','The goalkeeper’s reaction speed','The probability of scoring'],answer:0},
  {id:'cause',text:'Pressure occurs before the interception. What can we conclude?',choices:['Pressure definitely caused the mistake','The order is recorded; causation remains uncertain','Pressure had no influence'],answer:1},
  {id:'outcome',text:'What does a recorded goal tell us about the earlier interception?',choices:['It proves the pressure caused the interception','It proves every earlier pass was difficult','It confirms the finish, not the cause of the interception'],answer:2}]}];
export function studyAssignment(n){const branch=Math.floor(n)%4,order=branch%2?[1,0]:[0,1];return order.map((i,j)=>({case_id:STUDY_CASES[i].id,condition:(j+(branch>=2?1:0))%2?'crew':'records'}));}
export function scoreStudyTrial(caseId,answers){const c=STUDY_CASES.find(c=>c.id===caseId);if(!c||!c.questions.every(q=>Number.isInteger(answers[q.id])&&answers[q.id]>=0&&answers[q.id]<3))throw Error('Complete every question');return {case_id:caseId,correct:c.questions.filter(q=>q.answer===answers[q.id]).length,total:3,answers:Object.fromEntries(c.questions.map(q=>[q.id,answers[q.id]]))};}
export function aggregateStudy(records){const seen=new Set(),rows=[];for(const r of records){if(r.schema!=='btr.viewer-study.v2'||r.version!==STUDY_VERSION||r.consent!==true||typeof r.participant!=='string'||seen.has(r.participant)||r.trials?.length!==2)throw Error('Invalid, duplicate or incompatible participant record');seen.add(r.participant);const assignment=studyAssignment(r.assignment);r.trials.forEach((t,i)=>{if(t.case_id!==assignment[i].case_id||t.condition!==assignment[i].condition||!Number.isFinite(t.elapsed_seconds)||t.elapsed_seconds<0)throw Error('Invalid trial');rows.push({...scoreStudyTrial(t.case_id,t.answers),condition:t.condition,elapsed_seconds:t.elapsed_seconds});});}const summary={};for(const condition of ['records','crew']){const group=rows.filter(r=>r.condition===condition);summary[condition]={trials:group.length,correct:group.reduce((n,r)=>n+r.correct,0),questions:group.length*3,mean_task_seconds:group.length?Math.round(group.reduce((n,r)=>n+r.elapsed_seconds,0)/group.length):null};}return {participants:seen.size,summary,limits:['Small volunteer sample; report failures and participant familiarity.','Different scenarios and learning effects may influence results.','Timing includes reading and answering; it is not production time saved.','Crew content is saved model output or reviewed notes, identified per trial; this is not a live-model accuracy test.']};}
